INSERT INTO exec_knowledge_chunk (knowledge_id, chunk_index, page_number, content, content_length) VALUES
(4, 0, NULL, 'КАРТОЧКА РОЛИ: CDS Блока внутреннего контроля. Сотрудник: Кузьменко А.В. Роль: CDS Блока внутреннего контроля. Статус: назначен. Тип роли: дополнительная функциональная роль. Контур: Блок внутреннего контроля. Формат участия: матричный / совмещение с основной должностью. Связь с Центром: функционально связана с проектированием и последующей деятельностью ЦЦиРТКД. Источник полномочий: решение/назначение Блока. Не является отдельной штатной должностью в пока не созданном Центре. ВАЖНО: роль CDS — это назначение, отдельное от должности Кузьменко А.В. (Директор по цифровизации и развитию технологий внутреннего контроля) и отдельное от его будущей роли руководителя проектируемого Центра. Эти три статуса не следует смешивать при расчётах и в организационной модели кабинета.', 908),
(4, 1, NULL, 'Цель роли CDS: обеспечивать координацию работы Блока внутреннего контроля в области данных, цифровизации, автоматизации и применения искусственного интеллекта, выявлять перспективные инициативы и организовывать их проработку во взаимодействии с профильными подразделениями и центрами компетенций. Основные функции CDS: собирать потребности подразделений Блока в данных, автоматизации и ИИ; выявлять и формировать прикладные сценарии применения технологий; проводить первичную оценку ценности, реализуемости и рисков инициатив; консолидировать и приоритизировать инициативы Блока; координировать взаимодействие с ИТ, подразделениями данных, ИБ и центрами компетенций; содействовать подготовке пилотных решений; контролировать движение инициатив и достигнутые результаты; организовывать обмен знаниями и развитие внутреннего сообщества; обеспечивать соблюдение требований к данным, безопасности и ответственному применению ИИ; представлять интересы Блока в профильных рабочих группах.', 970),
(4, 2, NULL, 'Связь CDS с будущим Центром (ЦЦиРТКД): роль CDS является действующим функциональным механизмом координации цифровых инициатив Блока внутреннего контроля и одной из организационных предпосылок создания ЦЦиРТКД. После создания Центра функции CDS должны быть встроены в его операционную модель без дублирования полномочий. Компетенции для профиля CDS: управление портфелем цифровых инициатив — экспертный уровень; цифровая трансформация — продвинутый; применение данных и ИИ — продвинутый; бизнес-анализ — продвинутый; управление изменениями — продвинутый; межфункциональная координация — экспертный; оценка эффектов — продвинутый; управление рисками — продвинутый; коммуникация с руководством — экспертный.', 700);
